package com.paspeur.hello.build;

import org.junit.jupiter.api.Test;
import java.nio.file.Files;
import java.nio.file.Path;
import static org.junit.jupiter.api.Assertions.assertEquals;

/**
 * Bug 4 of 4 — an artifact made by hand, not by the build.
 * This reads build/generated/version.txt. The author created it once, by hand,
 * into build/ — which is git-ignored and wiped on every clean checkout. So it
 * exists on their machine but is regenerated by nobody on a clean clone.
 * Fix: make the BUILD produce this file (a task that runs before the tests), so
 * it is created reproducibly from what's committed — not left lying around.
 */
class GeneratedArtifactTest {

    @Test
    void readsGeneratedVersion() throws Exception {
        assertEquals("1.0.0", Files.readString(Path.of("build/generated/version.txt")).strip());
    }
}
